package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"

	"toml/internal/toml"
)

func main() {
	os.Exit(run(os.Stdin, os.Stdout, os.Stderr))
}

func run(stdin io.Reader, stdout, stderr io.Writer) int {
	document, err := io.ReadAll(stdin)
	if err != nil {
		fmt.Fprintf(stderr, "read TOML: %v\n", err)
		return 1
	}
	decoded, err := toml.Decode(document)
	if err != nil {
		fmt.Fprintf(stderr, "decode TOML: %v\n", err)
		return 1
	}
	if err := json.NewEncoder(stdout).Encode(decoded); err != nil {
		fmt.Fprintf(stderr, "encode JSON: %v\n", err)
		return 1
	}
	return 0
}

