// Package toml provides the TOML document boundary used by the decoder.
package toml

import (
	"bytes"
	"fmt"
	"strconv"
	"strings"
)

// Value is the lossless tagged representation of a decoded TOML value.
type Value struct {
	Type  string `json:"type"`
	Value string `json:"value"`
}

// Decode parses the supported TOML document bytes into tagged values.
func Decode(document []byte) (map[string]Value, error) {
	result := make(map[string]Value)
	for lineNumber, rawLine := range bytes.Split(document, []byte{'\n'}) {
		line := strings.TrimSpace(string(rawLine))
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		key, rawValue, ok := strings.Cut(line, "=")
		if !ok {
			return nil, fmt.Errorf("line %d: expected key/value assignment", lineNumber+1)
		}
		key = strings.TrimSpace(key)
		rawValue = strings.TrimSpace(rawValue)
		if !validKey(key) || rawValue == "" {
			return nil, fmt.Errorf("line %d: invalid assignment", lineNumber+1)
		}
		value, err := integerValue(rawValue)
		if err != nil {
			return nil, fmt.Errorf("line %d: %w", lineNumber+1, err)
		}
		result[key] = value
	}
	return result, nil
}

func validKey(key string) bool {
	if key == "" {
		return false
	}
	for _, r := range key {
		if !(r == '_' || r == '-' || r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9') {
			return false
		}
	}
	return true
}

func integerValue(raw string) (Value, error) {
	if strings.HasPrefix(raw, "[") || strings.HasPrefix(raw, "{") {
		return Value{}, fmt.Errorf("unsupported value")
	}
	parsed, err := strconv.ParseInt(raw, 10, 64)
	if err != nil {
		return Value{}, fmt.Errorf("invalid integer")
	}
	return Value{Type: "integer", Value: strconv.FormatInt(parsed, 10)}, nil
}

